// HasQuotaAccount applies the HasEdge predicate on the "quota_account" edge.
func HasQuotaAccount() predicate.MailLog {
	return predicate.MailLog(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, QuotaAccountTable, QuotaAccountColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasQuotaAccountWith applies the HasEdge predicate on the "quota_account" edge with a given conditions (other predicates).
func HasQuotaAccountWith(preds ...predicate.MailAccount) predicate.MailLog {
	return predicate.MailLog(func(s *sql.Selector) {
		step := newQuotaAccountStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MailLog) predicate.MailLog {
	return predicate.MailLog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MailLog) predicate.MailLog {
	return predicate.MailLog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MailLog) predicate.MailLog {
	return predicate.MailLog(sql.NotPredicates(p))
}
